hudson.tasks.Shell.command:
#!/bin/bash set -e
# Config bundle only -- no container images, no deploy scripts re-upload. tar -czf config-bundle.tar.gz -C pic-sure-all-in-one/monitoring prometheus grafana blackbox aws s3 --sse=AES256 cp config-bundle.tar.gz "s3://$stack_s3_bucket/monitoring/config-bundle.tar.gz"
# Secrets (monitoring.env, app-token, db-exporters.env) are OPERATOR-managed -- # this job never writes them.
